param(
    [Parameter(Mandatory=$true)][string]$ZipPath,
    [string]$BinaryDirectory='build/out'
)
$ErrorActionPreference='Stop'
$expected=@('dxgi.dll','DarksidersGenesisMod.asi')
$binaryRoot=(Resolve-Path -LiteralPath $BinaryDirectory).Path
$paths=@()
foreach($name in $expected){
    $path=Join-Path $binaryRoot $name
    $bytes=[IO.File]::ReadAllBytes($path)
    if($bytes.Length -lt 256 -or $bytes[0] -ne 77 -or $bytes[1] -ne 90){throw "Invalid PE: $name"}
    $pe=[BitConverter]::ToInt32($bytes,0x3C)
    if($pe -lt 64 -or $pe -gt $bytes.Length-24 -or [BitConverter]::ToUInt32($bytes,$pe) -ne 0x4550 -or [BitConverter]::ToUInt16($bytes,$pe+4) -ne 0x8664){throw "Invalid AMD64 module: $name"}
    $paths+=$path
}
if(Test-Path -LiteralPath $ZipPath){throw 'Numbered archive already exists; refusing overwrite'}
$parent=Split-Path -Parent $ZipPath
if($parent){New-Item -ItemType Directory -Path $parent -Force | Out-Null}
# The INI is generated by the ASI. Build documentation stays in GitHub.
Compress-Archive -LiteralPath $paths -DestinationPath $ZipPath -CompressionLevel NoCompression
Add-Type -AssemblyName System.IO.Compression.FileSystem
$zip=[IO.Compression.ZipFile]::OpenRead((Resolve-Path -LiteralPath $ZipPath))
try{
    $names=@($zip.Entries | ForEach-Object {$_.FullName})
    if($names.Count -ne 2 -or @($expected | Where-Object {$_ -cnotin $names}).Count){throw 'Expected exactly two binary root entries'}
    foreach($entry in $zip.Entries){
        if($entry.FullName.Contains('/') -or $entry.FullName.Contains('\')){throw 'Nested ZIP entry'}
        $stream=$entry.Open();$memory=[IO.MemoryStream]::new()
        try{
            $stream.CopyTo($memory)
            $actual=$memory.ToArray();$original=[IO.File]::ReadAllBytes((Join-Path $binaryRoot $entry.FullName))
            if([Convert]::ToBase64String($actual) -cne [Convert]::ToBase64String($original)){throw "Archived bytes differ: $($entry.FullName)"}
        }finally{$stream.Dispose();$memory.Dispose()}
    }
}finally{$zip.Dispose()}
Get-FileHash -LiteralPath $ZipPath -Algorithm SHA256
